          await api(`/model/set?profile=${encodeURIComponent(context.profile)}`,{method:"POST",body:JSON.stringify({scope:"auxiliary",task,provider:automatic?"auto":provider.value,model:automatic?"":model.value,reasoning_effort:reasoning.value||null})});
